#!/usr/bin/env bash
# Droit à l'image d'un mineur : validation en ligne par son parent (backend + champ « qualité » de la fiche admin).
# Prérequis : apply-fix-base-locale-seaweedfs.sh. MIGRATION : 20261213000000_guardian_consent.
# Usage (racine du repo) : bash apply-fix-circuit-parent.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/imageConsent/router.ts" 2>/dev/null | grep -qF "confirmGuardian:"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "photos : SeaweedFS" "revenir-base-locale.sh" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-base-locale-seaweedfs.sh"; exit 1; }
MODIFIED=("apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" "apps/web/src/app/api/media/image-consent/prefilled/route.ts" "apps/web/src/features/admin/users/legal/LegalInfoControl.tsx" "apps/web/src/features/admin/users/legal/LegalInfoFields.tsx" "e2e/data.mjs" "e2e/helpers.ts" "e2e/prepare.mjs" "packages/backend/src/email/templates/imageConsentNotice.ts" "packages/backend/src/modules/imageConsent/consentPdf.service.ts" "packages/backend/src/modules/imageConsent/imageConsentForm.service.ts" "packages/backend/src/modules/imageConsent/imageConsentOnline.service.ts" "packages/backend/src/modules/imageConsent/router.ts" "packages/backend/src/modules/privacy/exportMyData.service.ts" "packages/backend/src/modules/users/legalInfo.ts" "packages/contracts/src/legal/imageConsent.ts" "prisma/schema.prisma")
CREATED=("e2e/droit-a-l-image-parent.spec.ts" "packages/backend/src/email/templates/imageConsentGuardian.ts" "packages/backend/src/modules/imageConsent/imageConsentGuardian.service.ts" "prisma/migrations/20261213000000_guardian_consent/migration.sql")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "prisma/migrations/20261213000000_guardian_consent" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "confirmGuardian:" "packages/backend/src/modules/imageConsent/router.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

